1	#!/usr/bin/env node
2	/**
3	 * cite-sources.mjs — gate `cite-sources` (contract `kumitate-cite-sources-v1`).
4	 *
5	 *   node scripts/cite-sources.mjs [--readme PATH] [--sources PATH]
6	 *   node scripts/cite-sources.mjs --selftest
7	 *
8	 * A README map row (a line whose first non-space characters are `| `) may cite
9	 * a source id `S` + 3 or more digits. Each such id must be a row id in
10	 * corpus/SOURCES.md. One- and two-digit tokens (registry family ids S1–S11)
11	 * are not source ids and are ignored. This is the class routed as R58-V3:
12	 * corpus/README.md cited S121, which is not a row.
13	 *
14	 *   CITE_SOURCES: CLEAN cited=<n>                         exit 0
15	 *   CITE_SOURCES: DRIFT ghosts=<k> first=<id>             exit 1
16	 *   CITE_SOURCES: FAIL-CLOSED reason=<why>                exit 2
17	 *   CITE_SOURCES: USAGE ...                               exit 64
18	 *
19	 * The gate reads the two files and writes nothing.
20	 */
21	import { spawnSync } from 'node:child_process';
22	import { mkdtempSync, readFileSync, rmSync, writeFileSync, mkdirSync } from 'node:fs';
23	import { tmpdir } from 'node:os';
24	import { join, resolve } from 'node:path';
25	
26	const ID_RE = /\bS[0-9]{3,}\b/g;
27	
28	function usage() {
29	  process.stdout.write('CITE_SOURCES: USAGE node scripts/cite-sources.mjs [--readme PATH] [--sources PATH] | --selftest\n');
30	  process.exit(64);
31	}
32	
33	function registryIds(text) {
34	  const ids = new Set();
35	  for (const line of text.split('\n')) {
36	    const m = line.match(/^ {0,3}\|\s*(S[0-9]{3,})\s*\|/);
37	    if (m) ids.add(m[1]);
38	  }
39	  return ids;
40	}
41	
42	function citedIds(readme) {
43	  const cited = [];
44	  for (const line of readme.split('\n')) {
45	    if (!/^\s*\| /.test(line)) continue;
46	    const found = line.match(ID_RE);
47	    if (found) cited.push(...found);
48	  }
49	  return cited;
50	}
51	
52	function evaluate(readmeText, sourcesText) {
53	  const ids = registryIds(sourcesText);
54	  const cited = citedIds(readmeText);
55	  const ghosts = [];
56	  const seen = new Set();
57	  for (const id of cited) {
58	    if (ids.has(id) || seen.has(id)) continue;
59	    seen.add(id);
60	    ghosts.push(id);
61	  }
62	  if (ghosts.length) {
63	    return { code: 1, line: `CITE_SOURCES: DRIFT ghosts=${ghosts.length} first=${ghosts[0]}` };
64	  }
65	  return { code: 0, line: `CITE_SOURCES: CLEAN cited=${cited.length}` };
66	}
67	
68	function readOrFail(path, why) {
69	  try {
70	    return readFileSync(path, 'utf8');
71	  } catch {
72	    process.stdout.write(`CITE_SOURCES: FAIL-CLOSED reason=${why}\n`);
73	    process.exit(2);
74	  }
75	}
76	
77	function run(argv) {
78	  let readme = 'corpus/README.md';
79	  let sources = 'corpus/SOURCES.md';
80	  for (let i = 0; i < argv.length; i++) {
81	    const a = argv[i];
82	    if (a === '-h' || a === '--help') usage();
83	    else if (a === '--readme') { readme = argv[++i]; if (!readme) usage(); }
84	    else if (a === '--sources') { sources = argv[++i]; if (!sources) usage(); }
85	    else usage();
86	  }
87	  const readmeText = readOrFail(resolve(readme), 'README_UNREADABLE');
88	  const sourcesText = readOrFail(resolve(sources), 'SOURCES_UNREADABLE');
89	  const result = evaluate(readmeText, sourcesText);
90	  process.stdout.write(result.line + '\n');
91	  process.exit(result.code);
92	}
93	
94	function selftest() {
95	  const root = mkdtempSync(join(tmpdir(), 'cite-sources.'));
96	  const cases = [];
97	  const check = (name, ok, detail) => cases.push({ name, ok, detail });
98	  try {
99	    const rd = join(root, 'corpus');
100	    mkdirSync(rd, { recursive: true });
101	    const readme = join(rd, 'README.md');
102	    const sources = join(rd, 'SOURCES.md');
103	    const sourcesBody = '| id | source |\n|---|---|\n| S112 | example |\n| S122 | example |\n';
104	    writeFileSync(sources, sourcesBody);
105	    writeFileSync(readme, '| `knowledge/a.md` | cites S112 and S122 |\n');
106	    let r = evaluate(readFileSync(readme, 'utf8'), readFileSync(sources, 'utf8'));
107	    check('clean-known-ids', r.code === 0 && r.line.includes('CLEAN'), r.line);
108	
109	    writeFileSync(readme, '| `knowledge/failure-recovery-replay.md` | Temporal replay (S121) |\n');
110	    r = evaluate(readFileSync(readme, 'utf8'), readFileSync(sources, 'utf8'));
111	    check('ghost-s121', r.code === 1 && r.line.includes('first=S121'), r.line);
112	
113	    writeFileSync(readme, '| `knowledge/ops-watchers.md` | family S6 and S7 and S8 |\n');
114	    r = evaluate(readFileSync(readme, 'utf8'), readFileSync(sources, 'utf8'));
115	    check('family-ids-ignored', r.code === 0 && r.line.includes('CLEAN'), r.line);
116	
117	    writeFileSync(readme, '| `knowledge/a.md` | S121 and S999 |\n');
118	    r = evaluate(readFileSync(readme, 'utf8'), readFileSync(sources, 'utf8'));
119	    check('two-ghosts-first-named', r.code === 1 && r.line.includes('ghosts=2') && r.line.includes('first=S121'), r.line);
120	
121	    writeFileSync(readme, 'prose mentions S121 but is not a map row\n| `knowledge/a.md` | S112 |\n');
122	    r = evaluate(readFileSync(readme, 'utf8'), readFileSync(sources, 'utf8'));
123	    check('prose-outside-rows-ignored', r.code === 0, r.line);
124	
125	    writeFileSync(sources, 'not a table\n');
126	    writeFileSync(readme, '| `knowledge/a.md` | S112 |\n');
127	    r = evaluate(readFileSync(readme, 'utf8'), readFileSync(sources, 'utf8'));
128	    check('unparsed-registry-is-drift', r.code === 1 && r.line.includes('first=S112'), r.line);
129	
130	    writeFileSync(readme, 'no map rows\n');
131	    writeFileSync(sources, sourcesBody);
132	    r = evaluate(readFileSync(readme, 'utf8'), readFileSync(sources, 'utf8'));
133	    check('no-citations-clean', r.code === 0 && r.line.includes('cited=0'), r.line);
134	
135	    const help = awaitChild(['--help']);
136	    check('usage-64', help.status === 64 && help.stdout.includes('USAGE'), `status=${help.status}`);
137	  } finally {
138	    rmSync(root, { recursive: true, force: true });
139	  }
140	  const passed = cases.filter((c) => c.ok).length;
141	  const failed = cases.filter((c) => !c.ok);
142	  for (const c of cases) {
143	    process.stdout.write(`${c.ok ? 'PASS' : 'FAIL'} ${c.name}${c.ok ? '' : ' — ' + c.detail}\n`);
144	  }
145	  const line = `CITE_SOURCES_SELFTEST: ${failed.length ? 'FAIL' : 'PASS'} (${passed}/${cases.length})`;
146	  process.stdout.write(line + '\n');
147	  process.stdout.write(`VERDICT: ${failed.length ? 'FAIL' : 'PASS'}\n`);
148	  process.exit(failed.length ? 1 : 0);
149	}
150	
151	function awaitChild(args) {
152	  return spawnSync(process.execPath, [process.argv[1], ...args], { encoding: 'utf8' });
153	}
154	
155	const argv = process.argv.slice(2);
156	if (argv.includes('--selftest')) {
157	  selftest();
158	} else {
159	  run(argv);
160	}

