10	 * Eight checks over the committed bytes of <rev> (git archive, never the worktree):
11	 *   B1  scripts/cite-sources.mjs exists; its --selftest prints
12	 *       CITE_SOURCES_SELFTEST: PASS (8/8) and exits 0.
13	 *   B2  node scripts/cite-sources.mjs in the extraction prints
14	 *       CITE_SOURCES: CLEAN and exits 0.
15	 *   B3  the SKILL.md line containing "are gates" names nineteen (word or 19),
16	 *       the gate-registry table has exactly 19 `| gate |` rows, and one of
17	 *       those rows is named cite-sources.
18	 *   B4  the SCORECARD capabilities table has a row whose first cell is
19	 *       `cite-sources`, a row whose first cell is `receipt-evidence`, and the
20	 *       `readme-map` capability row contains `v2` and `16/16` and does not
21	 *       contain `files=135`.
22	 *   B5  node scripts/readme-map.mjs in the extraction prints README_MAP: CLEAN
23	 *       and .ufo/pins/readme-map.json covered includes
24	 *       lessons/round-58-verifier-spotcheck.md.
25	 *   B6  SCORECARD.md contains the literal `R58-V1 measured base held=2/5`.
26	 *   B7  corpus/lessons/round-59.md contains a line
27	 *       TIER59: A=<n> B=<n> C=<n> rows=<n> whose four integers equal this
28	 *       probe's own histogram of corpus/SOURCES.md at rev.
29	 *   B8  corpus/lessons/round-59.md contains the literals
30	 *       `a shared page is not automatically a duplicate` and
31	 *       `pin the duplicate group before adoption`.
32	 *
33	 * A drop-one mutant (EXPECTED_CHECKS still 8, one hold() removed) prints
34	 * checks-mismatch and never HELD. Frozen before any data seat scored.
35	 */
36	import { spawnSync } from 'node:child_process';
37	import { existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
38	import { tmpdir } from 'node:os';
39	import { join, resolve } from 'node:path';
40	
41	const RULE = 'A59';
42	const EXPECTED_CHECKS = 8;
43	const WORDS = { seventeen: 17, eighteen: 18, nineteen: 19, twenty: 20 };
44	
45	const [laneArg, rev, ...rest] = process.argv.slice(2);
46	if (!laneArg || !rev || rest.length) {
47	  process.stderr.write('REPAIR59: USAGE node repair59-probe.mjs <lane> <rev>\n');
48	  process.exit(64);
49	}
50	const lane = resolve(laneArg);
51	if (!existsSync(join(lane, '.git'))) {
52	  process.stderr.write(`REPAIR59: USAGE ${JSON.stringify(lane)} is not a git repo\n`);
53	  process.exit(64);
54	}
55	if (!/^[0-9a-f]{7,64}$/.test(rev)) {
56	  process.stderr.write('REPAIR59: USAGE <rev> must be a lowercase hex object name\n');
57	  process.exit(64);
58	}
59	
60	const checks = [];
61	const hold = (id, ok, detail) => checks.push({ id, ok, detail });
62	const T = mkdtempSync(join(tmpdir(), 'a59-probe.'));
63	
64	function finish(code, line) {
65	  rmSync(T, { recursive: true, force: true });
66	  process.stdout.write(line + '\n');
67	  for (const c of checks) process.stdout.write(` | ${c.id} ${c.ok ? 'PASS' : 'MISS'} ${c.detail}`);
68	  if (checks.length) process.stdout.write('\n');
69	  process.exit(code);
70	}
71	
72	try {
73	  const tar = spawnSync('bash', ['-lc',
74	    `git -C ${JSON.stringify(lane)} archive ${JSON.stringify(rev)} | tar -x -C ${JSON.stringify(T)}`],
75	    { encoding: 'utf8', timeout: 180000 });
76	  if (tar.status !== 0) {
77	    process.stderr.write(`REPAIR59: FAIL-CLOSED rev unreadable (${tar.status}) ${tar.stderr || ''}\n`);
78	    rmSync(T, { recursive: true, force: true });
79	    process.exit(2);
80	  }
81	  const readT = (p) => { try { return readFileSync(join(T, p), 'utf8'); } catch { return null; } };
82	
83	  {
84	    const self = spawnSync(process.execPath, ['scripts/cite-sources.mjs', '--selftest'],
85	      { cwd: T, encoding: 'utf8', timeout: 60000 });
86	    const ok = self.status === 0 && (self.stdout || '').includes('CITE_SOURCES_SELFTEST: PASS (8/8)');
87	    hold('B1', ok, ok ? 'selftest-8/8' : `status=${self.status} ${(self.stdout || self.stderr || '').slice(0, 120)}`);
88	  }
89	  {
90	    const run = spawnSync(process.execPath, ['scripts/cite-sources.mjs'],
91	      { cwd: T, encoding: 'utf8', timeout: 30000 });
92	    const ok = run.status === 0 && (run.stdout || '').includes('CITE_SOURCES: CLEAN');
93	    hold('B2', ok, ok ? 'clean' : `status=${run.status} ${(run.stdout || '').slice(0, 120)}`);
94	  }
95	  {
96	    const skill = readT('SKILL.md') || '';
97	    const gateLine = skill.split('\n').find((l) => l.includes('are gates')) || '';
98	    const word = gateLine.toLowerCase().match(/\b(seventeen|eighteen|nineteen|twenty)\b/);
99	    const digit = gateLine.match(/\b(1[7-9]|20)\b/);
100	    const named = word ? WORDS[word[1]] : (digit ? Number(digit[1]) : null);
101	    const rows = skill.split('\n').filter((l) => l.startsWith('| ') && l.includes('| gate |'));
102	    const has = rows.some((l) => /\|\s*cite-sources\s*\|/.test(l));
103	    const ok = named === 19 && rows.length === 19 && has;
104	    hold('B3', ok, `prose=${named} rows=${rows.length} cite-sources=${has}`);
105	  }
106	  {
107	    const sc = readT('SCORECARD.md') || '';
108	    const cap = sc.split('\n').filter((l) => l.startsWith('| `'));
109	    const cite = cap.some((l) => l.startsWith('| `cite-sources` |'));
110	    const receipt = cap.some((l) => l.startsWith('| `receipt-evidence` |'));
111	    const map = cap.find((l) => l.startsWith('| `readme-map` |')) || '';
112	    const ok = cite && receipt && map.includes('v2') && map.includes('16/16') && !map.includes('files=135');
113	    hold('B4', ok, `cite=${cite} receipt=${receipt} mapv2=${map.includes('v2')} 16/16=${map.includes('16/16')} stale135=${map.includes('files=135')}`);
114	  }
115	  {
116	    const pin = readT('.ufo/pins/readme-map.json') || '';
117	    const pinned = pin.includes('lessons/round-58-verifier-spotcheck.md');
118	    const map = spawnSync(process.execPath, ['scripts/readme-map.mjs'],
119	      { cwd: T, encoding: 'utf8', timeout: 30000 });
120	    const clean = map.status === 0 && (map.stdout || '').includes('README_MAP: CLEAN');
121	    hold('B5', pinned && clean, `pinned=${pinned} status=${map.status} ${(map.stdout || '').split('\n').pop()}`);
122	  }
123	  {
124	    const sc = readT('SCORECARD.md') || '';
125	    const ok = sc.includes('R58-V1 measured base held=2/5');
126	    hold('B6', ok, ok ? 'literal' : 'absent');
127	  }
128	  {
129	    const lesson = readT('corpus/lessons/round-59.md') || '';
130	    const sources = readT('corpus/SOURCES.md') || '';
131	    const hist = { A: 0, B: 0, C: 0, rows: 0 };
132	    for (const line of sources.split('\n')) {
133	      const m = line.match(/^ {0,3}\|\s*(S[0-9]{3,})\s*\|/);
134	      if (!m) continue;
135	      const cells = line.split('|').slice(1, -1).map((c) => c.trim());
136	      hist.rows += 1;
137	      const tier = cells[3];
138	      if (tier === 'A' || tier === 'B' || tier === 'C') hist[tier] += 1;
139	    }
140	    const want = `TIER59: A=${hist.A} B=${hist.B} C=${hist.C} rows=${hist.rows}`;
141	    const ok = lesson.includes(want);
142	    hold('B7', ok, ok ? want : `want ${want}`);
143	  }
144	  {
145	    const lesson = readT('corpus/lessons/round-59.md') || '';
146	    const a = lesson.includes('a shared page is not automatically a duplicate');
147	    const b = lesson.includes('pin the duplicate group before adoption');
148	    hold('B8', a && b, `nuance=${a} pin-first=${b}`);
149	  }
150	} catch (err) {
151	  process.stderr.write(`REPAIR59: FAIL-CLOSED ${err && err.message}\n`);
152	  rmSync(T, { recursive: true, force: true });
153	  process.exit(2);
154	}
155	
156	const held = checks.filter((c) => c.ok).length;
157	const mismatch = checks.length !== EXPECTED_CHECKS;
158	const full = rev.length >= 40 ? rev : rev;
159	const head = `REPAIR59: ${mismatch ? 'REPAIR59_UNMET' : (held === EXPECTED_CHECKS ? 'REPAIR59_HELD' : 'REPAIR59_UNMET')} held=${held}/${checks.length} checks=${EXPECTED_CHECKS} rev=${full} rule=${RULE} version=v1${mismatch ? ' checks-mismatch' : ''}`;
160	finish(held === EXPECTED_CHECKS && !mismatch ? 0 : 1, head);
